  ui_story_32170601_100_dialog_content = "Pasolo, we'll leave the decorating up to you. Once we're done making dinner, we can all sit down and properly enjoy this year's Spring Festival!",
  ui_story_32170601_101_dialog_content = "I-I'll do my best! And... Thank you for the red packets, everyone.",
  ui_story_32170601_102_dialog_content = "Hmm, now what was I saying earlier?",
  ui_story_32170601_103_dialog_content = "Oh yeah! You're never alone, Pasolo.",
